INSERT INTO items VALUES('workshop.now-or-usually.sort.1',1,'interactive.workshops',1,'grammar.present-contrast','rule-classification','sort','{"category":"grammar","title":"习惯还是此刻","gradeMin":3,"id":"workshop.now-or-usually.sort.1","type":"sort","context":"把每张卡放进符合本组规则的篮子。可以改放，不计速度；全部放好后一起检查。","prompt":"先点一张卡，再点它的篮子。","sorting":{"cards":[{"id":"c77252251adf7","text":"She reads every evening."},{"id":"ca4734e702177","text":"We play on Saturdays."},{"id":"c865143c74e7f","text":"She is reading now."},{"id":"c09d5ebc2bfbb","text":"We are playing at the moment."}],"groups":[{"id":"g0","label":"日常习惯"},{"id":"g1","label":"此刻正在进行"}]}}','{"answers":["[[\"c09d5ebc2bfbb\",\"g1\"],[\"c77252251adf7\",\"g0\"],[\"c865143c74e7f\",\"g1\"],[\"ca4734e702177\",\"g0\"]]"],"placements":{"c77252251adf7":"g0","ca4734e702177":"g0","c865143c74e7f":"g1","c09d5ebc2bfbb":"g1"},"solutionSentences":["She reads every evening. → 日常习惯","We play on Saturdays. → 日常习惯","She is reading now. → 此刻正在进行","We are playing at the moment. → 此刻正在进行"],"evidenceTargets":["workshop-target:grammar.present-contrast:c77252251adf7","workshop-target:grammar.present-contrast:ca4734e702177","workshop-target:grammar.present-contrast:c865143c74e7f","workshop-target:grammar.present-contrast:c09d5ebc2bfbb"],"explanation":"She reads every evening. → 日常习惯；We play on Saturdays. → 日常习惯；She is reading now. → 此刻正在进行；We are playing at the moment. → 此刻正在进行。读完整句子：经常、每天发生的习惯通常用一般现在时；此刻正在进行的动作通常用现在进行时。只用这些有明确情境的句子作对比。","hint":"读完整句子：经常、每天发生的习惯通常用一般现在时；此刻正在进行的动作通常用现在进行时。只用这些有明确情境的句子作对比。","family":"workshop-set-2c6b3582055fdc4a","workshopId":"now-or-usually"}','published');
