INSERT INTO items VALUES('workshop.irregular-past.repair.8',1,'interactive.workshops',1,'morphology.verb.irregular-past','sentence-editing','repair','{"category":"tense","title":"原形和过去式","gradeMin":4,"id":"workshop.irregular-past.repair.8","type":"repair","context":"目标意思：他们上周一乘了公交车。 找到一处需要调整的词块，只改这一处。","prompt":"点选一个词块，填写符合情境的新词或短语。","editing":{"parts":[{"id":"p0","text":"They"},{"id":"p1","text":"taked"},{"id":"p2","text":"the"},{"id":"p3","text":"bus"},{"id":"p4","text":"last"},{"id":"p5","text":"Monday"},{"id":"p6","text":"."}]}}','{"answers":["[\"p1\",\"took\"]"],"repairs":[{"partId":"p1","replacements":["took"]}],"solutionSentences":["They took the bus last Monday."],"evidenceTargets":["workshop-target:morphology.verb.irregular-past:ce0a6230e370d"],"explanation":"They took the bus last Monday. 他们上周一乘了公交车。 go/went、eat/ate、see/saw、take/took是不规则变化，不能直接加ed。本组先认原形与过去式，再放进过去的句子。","hint":"go/went、eat/ate、see/saw、take/took是不规则变化，不能直接加ed。本组先认原形与过去式，再放进过去的句子。","family":"workshop-sentence-10129bf8cfea6521","workshopId":"irregular-past"}','published');
