INSERT INTO items VALUES('workshop.perfect-or-past.sort.1',1,'interactive.workshops',1,'grammar.present-perfect.intro','rule-classification','sort','{"category":"tense","title":"经历和明确过去","gradeMin":6,"id":"workshop.perfect-or-past.sort.1","type":"sort","context":"把每张卡放进符合本组规则的篮子。可以改放，不计速度；全部放好后一起检查。","prompt":"先点一张卡，再点它的篮子。","sorting":{"cards":[{"id":"c16c063dba156","text":"I have seen a rainbow before."},{"id":"c75076c9fb129","text":"She has visited the museum twice."},{"id":"cec4a321c8525","text":"I saw a rainbow yesterday."},{"id":"c32c0ff83ecd5","text":"She visited the museum last week."}],"groups":[{"id":"g0","label":"到现在为止的经历"},{"id":"g1","label":"明确过去时间的事件"}]}}','{"answers":["[[\"c16c063dba156\",\"g0\"],[\"c32c0ff83ecd5\",\"g1\"],[\"c75076c9fb129\",\"g0\"],[\"cec4a321c8525\",\"g1\"]]"],"placements":{"c16c063dba156":"g0","c75076c9fb129":"g0","cec4a321c8525":"g1","c32c0ff83ecd5":"g1"},"solutionSentences":["I have seen a rainbow before. → 到现在为止的经历","She has visited the museum twice. → 到现在为止的经历","I saw a rainbow yesterday. → 明确过去时间的事件","She visited the museum last week. → 明确过去时间的事件"],"evidenceTargets":["workshop-target:grammar.present-perfect.intro:c16c063dba156","workshop-target:grammar.present-perfect.intro:c75076c9fb129","workshop-target:grammar.present-perfect.intro:cec4a321c8525","workshop-target:grammar.present-perfect.intro:c32c0ff83ecd5"],"explanation":"I have seen a rainbow before. → 到现在为止的经历；She has visited the museum twice. → 到现在为止的经历；I saw a rainbow yesterday. → 明确过去时间的事件；She visited the museum last week. → 明确过去时间的事件。这里用现在完成时谈到现在为止的经历，用一般过去时说明yesterday、last week等明确的过去时间。现在完成时中have/has后要用过去分词。","hint":"这里用现在完成时谈到现在为止的经历，用一般过去时说明yesterday、last week等明确的过去时间。现在完成时中have/has后要用过去分词。","family":"workshop-set-c231dd6c1a436874","workshopId":"perfect-or-past"}','published');
