INSERT INTO items VALUES('workshop.perfect-or-past.repair.1',1,'interactive.workshops',1,'grammar.present-perfect.intro','sentence-editing','repair','{"category":"tense","title":"经历和明确过去","gradeMin":6,"id":"workshop.perfect-or-past.repair.1","type":"repair","context":"目标意思：我以前见过彩虹。 找到一处需要调整的词块，只改这一处。","prompt":"点选一个词块，填写符合情境的新词或短语。","editing":{"parts":[{"id":"p0","text":"I"},{"id":"p1","text":"have"},{"id":"p2","text":"saw"},{"id":"p3","text":"a"},{"id":"p4","text":"rainbow"},{"id":"p5","text":"before"},{"id":"p6","text":"."}]}}','{"answers":["[\"p2\",\"seen\"]"],"repairs":[{"partId":"p2","replacements":["seen"]}],"solutionSentences":["I have seen a rainbow before."],"evidenceTargets":["workshop-target:grammar.present-perfect.intro:c16c063dba156"],"explanation":"I have seen a rainbow before. 我以前见过彩虹。 这里用现在完成时谈到现在为止的经历，用一般过去时说明yesterday、last week等明确的过去时间。现在完成时中have/has后要用过去分词。","hint":"这里用现在完成时谈到现在为止的经历，用一般过去时说明yesterday、last week等明确的过去时间。现在完成时中have/has后要用过去分词。","family":"workshop-sentence-c2a96532c3815330","workshopId":"perfect-or-past"}','published');
